parameters.text:
=You are an experienced recruiter and resume coach. Compare the resume below against the job description and score the match from 0 to 100. Set verdict to "strong" when the candidate is clearly a fit, "partial" when they could be a fit with edits, and "weak" when the gap is large. List the important keywords from the job description that are missing from the resume, the genuine strengths, concrete improvements the candidate should make, and a rewritten professional summary tailored to this role.

Target role: {{ $('Resume Review Form').item.json['Target job title'] }}

Job description:
{{ $('Resume Review Form').item.json['Job description'] }}

Resume:
{{ $json.text }}

parameters.jsCode:
const src = $json.output || $json;
const f = $('Resume Review Form').item.json;
const join = function (x) { return Array.isArray(x) ? x.join('; ') : (x || ''); };
const bullets = function (x) { return Array.isArray(x) ? x.map(function (i) { return '- ' + i; }).join('\n') : (x || ''); };
return {
  email: f['Your email'] || '',
  jobTitle: f['Target job title'] || '',
  matchScore: Number(src.match_score) || 0,
  verdict: String(src.verdict || 'partial').toLowerCase(),
  missingKeywords: join(src.missing_keywords),
  strengths: join(src.strengths),
  improvements: join(src.improvements),
  improvementList: bullets(src.improvements),
  missingList: bullets(src.missing_keywords),
  rewrittenSummary: src.rewritten_summary || ''
};
